def min_crew_size(required, people):
    m = len(required)
    if m == 0:
        return 0
    idx = {s: i for i, s in enumerate(required)}
    masks = []
    for person in people:
        mask = 0
        for s in person:
            if s in idx:
                mask |= 1 << idx[s]
        masks.append(mask)
    full = (1 << m) - 1
    INF = float('inf')
    dp = [INF] * (1 << m)
    dp[0] = 0
    for state in range(1 << m):
        if dp[state] == INF:
            continue
        for mask in masks:
            nxt = state | mask
            if dp[nxt] > dp[state] + 1:
                dp[nxt] = dp[state] + 1
    return dp[full]
